const prepHexById={'s6-abandoned-claim':'0,-1','s6-western-sound':'0,-1','s6-haul-grounds':'0,-1','s6-examine-tracks':'0,-1','s6-assess-masonry':'0,-1','s6-survey-south':'0,-1','s6-traveller':'1,-2','s6-pack-animal':'1,-2','s6-route-exchange':'1,-2','s6-region-a1':'0,-4','s6-region-a2':'0,-4','s6-region-a3':'0,-4','s6-region-b1':'1,-4','s6-region-b2':'1,-4','s6-region-b3':'1,-4'};
const hexLabels={'0,0':'Greywake','0,-1':'Stripped Yards','1,0':'Old Marker Wash','2,0':'Grey Seep Fields','2,-1':'Pale Tracts','2,-3':'Sunken Relay','0,-2':'Digger Ruin','1,-2':'Traveller preparation','0,-4':'Regional preparation','1,-4':'Glasswind'};
let selectedHex='all',prepQuery='',prepKind='all',prepScope='relevant',liveContext=null,contextBusy=false,contextError='',contextChecked=false;
let localRegistry={},localSourceFiles={},loadedSourceSession='';
const legacySession=()=>session==='Session Six';
const registryEntry=c=>fullGM()&&c&&Object.hasOwn(localRegistry,c.id)?localRegistry[c.id]:null;
const cardHex=c=>registryEntry(c)?.hex||((legacySession()||String(c?.id).startsWith('s6-'))?prepHexById[c?.id]:null)||'unassigned';
function currentHex(){if(!liveContext||liveContext.session!==session||contextError)return '';const explicit=String(liveContext.hex??'').trim().replace(/[()+\s]/g,'');if(/^-?\d+,-?\d+$/.test(explicit))return explicit.split(',').map(Number).join(',');const norm=v=>String(v||'').trim().toLowerCase().replace(/^the\s+/,'');const location=norm(liveContext.location);if(!location)return '';const keys=new Set([...Object.keys(hexLabels),...Object.keys(localMaps)]);const matches=[...keys].filter(k=>[hexLabels[k],localMaps[k]?.title,localHexLabel(k)].some(v=>v&&norm(v)===location));return matches.length===1?matches[0]:'';}
function relevance(c){const h=currentHex(),k=cardHex(c);if(h&&h===k)return 2;if(h&&k!=='unassigned'){const [a,b]=h.split(',').map(Number),[x,y]=k.split(',').map(Number);if(Math.max(Math.abs(a-x),Math.abs(b-y),Math.abs(a+b-x-y))===1)return 1;}return 0;}
async function pullContext(){if(contextBusy||!gm())return;contextBusy=true;try{const res=await fetch('https://tmqxxgzqiccclcjagdsh.supabase.co/rest/v1/live_scene_display?display_key=eq.current&select=revision,scene,updated_at',{headers:{apikey:'sb_publishable_zML4qGtgQgMALEXFJn501w_1imfz8wl'},cache:'no-store'});if(!res.ok)throw Error('Live scene HTTP '+res.status);const rows=await res.json();const next=rows[0]?.scene;if(!next||!next.session||!next.location)throw Error('Live scene has no session or location');if(!fullGM())return;liveContext={session:next.session,location:next.location,hex:next.hex,party:Array.isArray(next.party)?next.party:[]};contextError='';}catch(e){contextError=String(e.message||e);}finally{contextBusy=false;contextChecked=true;if(gm())mount();}}
function renderLivePrepContext(){const valid=liveContext&&liveContext.session===session&&!contextError;const strip=document.querySelector('#gmOperationsView .gm-status-strip');const values={'SESSION':valid?liveContext.session:session||'Current','PARTY LOCATION':valid?liveContext.location:contextError?'Live context unavailable':'Connecting to live context…','ACTIVE PARTY':valid?liveContext.party.join(' · ')||'—':'—'};for(const cell of strip?.children||[]){const label=cell.querySelector('small')?.textContent;const value=cell.querySelector('strong');if(value&&Object.hasOwn(values,label)&&value.textContent!==values[label])value.textContent=values[label];}return contextError?'Live context unavailable — '+contextError+'. Showing available preparation.':!contextChecked?'Connecting to live context…':!valid?'Live scene and preparation session do not match. Showing available preparation.':!currentHex()?'Live location: '+liveContext.location+' · no unique mapped hex. Showing available preparation.':'Live location: '+liveContext.location+' · mapped hex '+currentHex();}
const sourcePath=p=>typeof p==='string'&&p.endsWith('.md')&&!p.startsWith('/')&&!p.split('/').some(x=>!x||x==='.'||x==='..')&&!p.includes('\\');

let localMaps={},localArea='C',localMapOpen=false;
function parseLocalMaps(note){
 const m=(note||'').match(/^\x60\x60\x60json\s*\n([\s\S]*?)^\x60\x60\x60\s*$/m);if(!m)return {};
 try{const parsed=JSON.parse(m[1]),out={};for(const [key,v] of Object.entries(parsed)){if(!/^-?\d+,-?\d+$/.test(key)||!v||typeof v.title!=='string'||!Array.isArray(v.areas)||v.areas.length!==7)continue;const keys=new Set(['N','NE','E','S','SW','W','C']);if(!v.areas.every(a=>a&&keys.delete(a.key)&&typeof a.title==='string'&&typeof a.terrain==='string'&&Array.isArray(a.cards)&&a.cards.every(id=>typeof id==='string'&&(!prepHexById[id]||prepHexById[id]===key))))continue;out[key]=v;}return out;}catch{return {};}
}

let terrainLayers={terrain:true,grid:false,locations:true,routes:true,ecology:false,people:false,hazards:false,party:false};
let selectedLocalCard='';
let terrainCamera={zoom:1,x:250,y:226},terrainExpanded=false,terrainDrag=null,terrainSuppressClick=false;
const terrainBase={w:416,h:468};
function terrainViewBox(){const w=terrainBase.w/terrainCamera.zoom,h=terrainBase.h/terrainCamera.zoom;return [terrainCamera.x-w/2,terrainCamera.y-h/2,w,h].join(' ');}
function resetTerrainCamera(){terrainCamera={zoom:1,x:250,y:226};}
function layoutTerrainLabels(){
 const svg=document.querySelector('[data-terrain-svg]');if(!svg)return;
 const z=terrainCamera.zoom, w=terrainBase.w/z,h=terrainBase.h/z,l=terrainCamera.x-w/2,t=terrainCamera.y-h/2;
 const nodes=[...svg.querySelectorAll('.gw-terrain-marker')].map(el=>{const m=el.getAttribute('transform').match(/translate\(([-\d.]+),([-\d.]+)\)/);return m?{el,x:Number(m[1]),y:Number(m[2]),active:el.getAttribute('aria-pressed')==='true'}:null;}).filter(Boolean).sort((a,b)=>Number(b.active)-Number(a.active));
 const taken=nodes.map(n=>({x:n.x-11/z,y:n.y-11/z,w:22/z,h:22/z}));const overlaps=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
 for(const n of nodes){const pin=n.el.querySelector('[data-map-pin]'),group=n.el.querySelector('[data-map-label]'),label=n.el.querySelector('[data-map-label-text]');if(!pin||!group||!label)continue;pin.setAttribute('transform','scale('+1/z+')');group.setAttribute('transform','scale('+1/z+')');group.style.display='';label.setAttribute('x','0');label.setAttribute('y','0');label.setAttribute('text-anchor','start');
 const width=label.getComputedTextLength()+6, height=17;
 const candidates=[[13,4],[-width-13,4],[-width/2,-17],[-width/2,25],[13,-15],[-width-13,-15],[13,23],[-width-13,23]];
 let placed=false;for(const [dx,dy] of candidates){const b={x:n.x+dx/z,y:n.y+(dy-13)/z,w:width/z,h:height/z};if(b.x<l+3/z||b.y<t+3/z||b.x+b.w>l+w-3/z||b.y+b.h>t+h-3/z||taken.some(k=>overlaps(k,b)))continue;label.setAttribute('x',String(dx));label.setAttribute('y',String(dy));taken.push(b);placed=true;break;}
 if(!placed&&!n.active)group.style.display='none';else if(!placed){label.setAttribute('x','12');label.setAttribute('y','-17');}
 }
}
function syncTerrainCamera(){const el=document.querySelector('[data-terrain-svg]');if(el)el.setAttribute('viewBox',terrainViewBox());const label=document.querySelector('[data-map-zoom-label]');if(label)label.textContent=Math.round(terrainCamera.zoom*100)+'%';layoutTerrainLabels();}
function zoomTerrain(factor){terrainCamera.zoom=Math.max(1,Math.min(4,terrainCamera.zoom*factor));if(terrainCamera.zoom===1)resetTerrainCamera();syncTerrainCamera();}
function closeTerrainExpanded(){if(terrainExpanded){terrainExpanded=false;mount();}}

const terrainCSS="\n.gw-terrain-workspace{border:1px solid #82724b;border-radius:8px;background:#181b16;padding:16px;margin:12px 0;color:#e8dfc9}\n.gw-terrain-workspace button{background:#2e2b20;color:#eadab4;border:1px solid #8b764d;border-radius:4px;padding:8px 11px;font:600 13px/1.35 system-ui,sans-serif;cursor:pointer;min-height:34px}\n.gw-terrain-workspace button:hover,.gw-terrain-workspace button:focus-visible{background:#4c4129;border-color:#d2ae66;outline:2px solid #d2ae66;outline-offset:2px}\n.gw-terrain-workspace button[aria-pressed=true],.gw-terrain-workspace button[data-private-pin]{background:#b99752;color:#171711;border-color:#d7b46f}\n.gw-terrain-layout{display:grid;grid-template-columns:minmax(0,1.85fr) minmax(250px,1fr);gap:14px;align-items:start}\n.gw-terrain-canvas{position:relative;overflow:hidden;border-radius:6px;background:#222820;border:1px solid #62563a;min-height:440px;display:flex;align-items:center;justify-content:center}\n.gw-terrain-canvas svg{width:100%;height:min(69vh,720px);display:block;touch-action:none;user-select:none;cursor:grab}\n.gw-terrain-canvas svg.gw-dragging{cursor:grabbing}\n.gw-terrain-marker,.gw-terrain-sector{cursor:pointer}\n.gw-terrain-marker:focus-visible{outline:none}\n.gw-terrain-marker:focus-visible circle:first-child{stroke:#fff0bf;stroke-width:3}\n.gw-map-tools{position:absolute;right:9px;bottom:25px;display:flex;gap:5px;align-items:center;background:#151711ed;border:1px solid #766240;padding:5px;border-radius:5px;z-index:2}\n.gw-map-tools button{padding:5px 9px;min-height:30px}.gw-map-tools span{font:12px system-ui,sans-serif;color:#e8d8af;min-width:37px;text-align:center}\n.gw-map-north{position:absolute;top:9px;left:11px;font:600 13px system-ui,sans-serif;color:#f1deb0;pointer-events:none;text-shadow:0 1px 3px #000}\n.gw-map-caption{position:absolute;left:0;bottom:5px;width:100%;text-align:center;font:10px system-ui,sans-serif;color:#e7d6ac;pointer-events:none}\n.gw-terrain-side{border:1px solid #62563a;background:#25291f;padding:16px;border-radius:6px;position:sticky;top:80px;max-height:calc(69vh + 2px);overflow:auto;scrollbar-color:#857044 #24271f}\n.gw-terrain-workspace .gw-terrain-side p,.gw-terrain-workspace .gw-terrain-side li,.gw-terrain-workspace .gw-terrain-side td{font-size:15px!important;line-height:1.6!important;color:#e0d8c5!important}\n.gw-terrain-side h3{font-size:21px!important;line-height:1.25;margin:9px 0 10px}\n.gw-terrain-side small{font:600 11px system-ui,sans-serif;color:#c9b894;letter-spacing:.055em}\n.gw-terrain-side .gw-location-art-pending{font:12px system-ui,sans-serif;color:#c3b497;padding:9px 0;border-bottom:1px solid #62563a}\n.gw-terrain-workspace.gw-terrain-expanded{position:fixed;inset:10px;z-index:2147483000;margin:0;overflow:auto;box-shadow:0 0 0 100vmax #111b}\n.gw-terrain-expanded .gw-terrain-canvas svg{height:calc(100vh - 210px);max-height:none}\n.gw-terrain-expanded .gw-terrain-side{top:0;max-height:calc(100vh - 210px)}\n@media(max-width:780px){.gw-terrain-layout{grid-template-columns:1fr}.gw-terrain-side{position:static;max-height:none}.gw-terrain-canvas{min-height:320px}.gw-terrain-canvas svg{height:min(62vh,560px)}}\n";
