const layerNames={terrain:'Terrain',grid:'Hex grid',locations:'Locations',routes:'Routes',ecology:'Ecology',people:'People',hazards:'Hazards',party:'Party'};
function terrainSvg(kind){
 const west=kind==='0,-4';
 const contours=west?Array.from({length:9},(_,i)=>'<ellipse cx="240" cy="245" rx="'+(210-i*18)+'" ry="'+(170-i*14)+'" transform="rotate(-18 240 245)" fill="'+(i%2?'#8c7d61':'#a39272')+'" stroke="#655a46" stroke-width="1.4" opacity=".92"/>').join(''):Array.from({length:14},(_,i)=>'<path d="M'+(i*42-65)+' -15 Q'+(i*42-110)+' 125 '+(i*42-32)+' 220 T'+(i*42+5)+' 470" stroke="'+(i%3===0?'#c6bda3':'#777567')+'" stroke-width="'+(i%3===0?18:7)+'" fill="none" opacity=".8"/>').join('');
 const marks=west?Array.from({length:8},(_,i)=>'<path d="M'+(115+i*9)+' '+(125+i*18)+' Q230 '+(165+i*14)+' '+(345-i*11)+' '+(115+i*20)+'" stroke="#c7b48c" stroke-width="5" fill="none"/><path d="M'+(115+i*9)+' '+(129+i*18)+' Q230 '+(169+i*14)+' '+(345-i*11)+' '+(119+i*20)+'" stroke="#514b3a" stroke-width="1.6" fill="none"/>').join(''):'<path d="M245 -10 C180 80 280 150 220 220 S275 350 245 475" stroke="#423f37" stroke-width="28" fill="none"/><path d="M380 20 Q410 165 350 245 T390 440" stroke="#756d4e" stroke-width="46" fill="none" opacity=".85"/>';
 const ridges=west?Array.from({length:7},(_,i)=>'<path d="M'+(385+i*13)+' -20 L'+(360+i*15)+' 83 L'+(390+i*14)+' 155 L'+(365+i*16)+' 220 L'+(405+i*11)+' 302 L'+(395+i*14)+' 470" stroke="#6e6958" stroke-width="9" fill="none"/>').join(''):'';
 const flecks=Array.from({length:190},(_,i)=>{const x=(i*137.53)%500,y=(i*79.39)%470;return '<ellipse cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" rx="'+(1+i%4)+'" ry="'+(0.6+i%3*.5)+'" fill="'+(i%2?'#e1d0a4':'#514b3a')+'" opacity=".2"/>';}).join('');
 return '<g pointer-events="none"><rect width="500" height="470" fill="#a49373"/>'+contours+marks+ridges+flecks+'</g>';
}
// Shared point-up hex geometry: +q east, +r northeast on screen.
function pointUpHex(radius){const a=Math.sqrt(3)*radius/2,b=radius/2;return [[0,-radius],[a,-b],[a,b],[0,radius],[-a,b],[-a,-b]].map(p=>p.map(n=>Number(n.toFixed(4))).join(',')).join(' ');}
function hexOffset(q,r,radius){return [Math.sqrt(3)*radius*(q+r/2),-1.5*radius*r];}
function localHexGrid(){const radius=226/3,points=pointUpHex(radius),out=[];for(let r=-3;r<=3;r++)for(let q=-3;q<=3;q++){if(Math.max(Math.abs(q),Math.abs(r),Math.abs(q+r))>3)continue;const [x,y]=hexOffset(q,r,radius);out.push('<polygon points="'+points+'" transform="translate('+(250+x)+','+(226+y)+')" fill="none" stroke="#eee0bd" stroke-opacity=".65" stroke-width="1.2" vector-effect="non-scaling-stroke"/>');}return '<g pointer-events="none" aria-hidden="true">'+out.join('')+'</g>';}
function localMapHtml(){
 const map=fullGM()?localMaps[selectedHex]:null;
 const title=map?.title||localHexLabel(selectedHex);
 const pts={N:[250,82],NE:[374,154],E:[374,298],S:[250,370],SW:[126,298],W:[126,154],C:[250,226]};
 const area=map?.areas.find(a=>a.key===localArea);
 const findCard=id=>cards?.find(c=>c.id===id);
 const areaCards=(area?.cards||[]).map(findCard).filter(Boolean);
 const chosen=areaCards.find(c=>c.id===selectedLocalCard)||areaCards[0];
 const privatePrep=chosen?privateCard(chosen):null;
 const buttons=ids=>ids.map(findCard).filter(Boolean).map(c=>'<button type="button" data-view-prep="'+esc(c.id)+'" style="padding:9px;border:1px solid #88734b;background:#302b20;color:#ead9b1;text-align:left">'+esc(shownTitle(c))+' ↗</button>').join('');
 const fallbackRoute=selectedHex==='0,-4'?'M250 8 Q215 100 250 226 L250 370 M250 226 Q315 240 374 298 L490 298':'M250 8 Q218 115 250 226 L250 450 M250 82 Q398 125 374 298 Q340 365 250 370 M10 298 L126 298 Q100 130 250 82';
 const route=Array.isArray(map?.routePaths)&&map.routePaths.every(p=>typeof p==='string'&&/^[MLQCSHTVAZmlqcshtvaz0-9., +\-]+$/.test(p))?map.routePaths.join(' '):fallbackRoute;
 const adjustedMarker=(a,x,y)=>{const p=map?.markers?.[a.key];return p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=55&&p.x<=445&&p.y>=0&&p.y<=452?[p.x-x,p.y-y]:[0,0];};

 const markerPoint=a=>{const [x,y]=pts[a.key];const [dx,dy]=regionTerrain(selectedHex)?adjustedMarker(a,x,y):[0,0];return [x+dx,y+dy];};
 const sectors=terrainLayers.grid?localHexGrid():'';
 const markers=map?.areas.map(a=>{const [x,y]=markerPoint(a),active=a.key===localArea,show=terrainLayers.locations||active;if(!show)return '';const symbol=a.cards.length?(a.cards.length>1?String(a.cards.length):'◇'):'·';return '<g role="button" tabindex="0" aria-label="'+esc(a.title)+'" aria-pressed="'+active+'" data-local-area="'+esc(a.key)+'" class="gw-terrain-marker" transform="translate('+x+','+y+')"><title>'+esc(a.title)+'</title><g data-map-pin><circle r="16" fill="transparent"/>'+(active?'<circle r="14" fill="#efd18b" fill-opacity=".22" stroke="#f8df9b" stroke-width="2"/>':'')+'<circle r="'+(a.cards.length?9:5)+'" fill="#28251d" stroke="'+(active?'#fff0bf':'#e1c384')+'" stroke-width="'+(active?2:1.5)+'"/><text y="3.8" text-anchor="middle" font-size="'+(a.cards.length?11:8)+'" font-weight="700" fill="#f6d99a" pointer-events="none">'+esc(symbol)+'</text></g><g data-map-label pointer-events="none"><text data-map-label-text font-size="11.5" font-weight="700" fill="#fff2d4" stroke="#30291d" stroke-width="3.5" paint-order="stroke" stroke-linejoin="round">'+esc(a.title)+'</text></g></g>';}).join('')||'';
 const svg=map?'<div class="gw-terrain-canvas"><svg data-terrain-svg viewBox="'+terrainViewBox()+'" aria-label="Local terrain map. Drag to pan; use zoom buttons or mouse wheel."><defs><clipPath id="gwLocalTerrainClip"><path d="M250 0 L445 112 L445 339 L250 452 L55 339 L55 112 Z"/></clipPath></defs><g clip-path="url(#gwLocalTerrainClip)">'+(terrainLayers.terrain?terrainLayerMarkup(selectedHex):'<rect width="500" height="470" fill="#353a30"/>')+(terrainLayers.routes?'<path d="'+route+'" fill="none" stroke="#382d1d" stroke-width="5.5" stroke-opacity=".7" pointer-events="none"/><path d="'+route+'" fill="none" stroke="#efe0b7" stroke-width="2.3" stroke-dasharray="6 5" pointer-events="none"/>':'')+sectors+'</g><path d="M250 0 L445 112 L445 339 L250 452 L55 339 L55 112 Z" fill="none" stroke="#d4b779" stroke-width="1.6" pointer-events="none"/>'+markers+'</svg><div class="gw-map-north" aria-hidden="true">N ↑</div><div class="gw-map-tools" aria-label="Map controls"><button type="button" data-map-action="in" aria-label="Zoom in">+</button><span data-map-zoom-label>'+Math.round(terrainCamera.zoom*100)+'%</span><button type="button" data-map-action="out" aria-label="Zoom out">−</button><button type="button" data-map-action="fit">Fit</button><button type="button" data-map-action="expand">'+(terrainExpanded?'Exit expanded view':'Expand')+'</button></div><span class="gw-map-caption">'+(regionTerrain(selectedHex)?'REGIONAL ARTWORK · PROVISIONAL MARKERS':'SCHEMATIC TERRAIN · NOT A SURVEY')+'</span></div>':'';
 const toggles=Object.entries(layerNames).map(([k,v])=>'<button type="button" data-terrain-layer="'+k+'" aria-pressed="'+terrainLayers[k]+'" style="border:1px solid #82724b;background:'+(terrainLayers[k]?'#69532a':'#25291f')+';color:#f0e5ca;border-radius:4px;padding:7px 10px">'+v+'</button>').join('');
 const contextLayers=['ecology','people','hazards','party'].filter(k=>terrainLayers[k]).map(k=>'<div style="border-top:1px solid #62563a;margin-top:12px;padding-top:8px"><strong>'+layerNames[k]+'</strong><p>'+({ecology:'Habitat and movement are described in the regional encounter record; no exact territories mapped yet.',people:'No established people positions in this hex. Use the regional encounter record for conditional encounters.',hazards:'Review the selected area terrain and local record. Exact hazard footprints are not surveyed.',party:'Consult the live scene for the current party position; no local party marker is assumed.'})[k]+'</p></div>').join('');
 const areaChooser='<label style="display:block;margin-bottom:12px;color:#c9b894;font-size:12px">Browse location<select data-local-area-select style="display:block;width:100%;margin-top:5px;padding:8px;background:#1c2018;color:#e8dfc9;border:1px solid #82724b;border-radius:4px">'+(map?.areas||[]).map(a=>'<option value="'+esc(a.key)+'"'+(a.key===localArea?' selected':'')+'>'+esc(a.title)+'</option>').join('')+'</select></label>'; const side='<aside class="gw-terrain-side">'+areaChooser+'<small>SELECTED AREA · PROVISIONAL</small><h3>'+esc(area?.title||'Select an area')+'</h3><p>'+esc(area?.terrain||'')+'</p>'+(areaCards.length?'<div style="display:flex;gap:6px;flex-wrap:wrap">'+areaCards.map(c=>'<button type="button" data-local-card="'+esc(c.id)+'" aria-pressed="'+(chosen?.id===c.id)+'">'+esc(shownTitle(c))+'</button>').join('')+'</div>':'<p>No fixed preparation here. Explore freely.</p>')+(chosen?'<hr>'+(artMarkup(chosen,true)||'<div class="gw-location-art-pending">No dedicated location image loaded.</div>')+'<h3>'+esc(shownTitle(chosen))+'</h3>'+(privatePrep?markdownLocal(privatePrep.body):'<p>'+esc(chosen.detail)+'</p>')+'<div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" data-view-prep="'+esc(chosen.id)+'">Full record ↗</button>'+(privatePrep?'<button type="button" data-private-pin="'+esc(chosen.id)+'">Pin private card to RUN</button>':'')+'</div>':'')+contextLayers+'</aside>';
 ensureTerrainStyle();return '<div class="gw-terrain-workspace'+(terrainExpanded?' gw-terrain-expanded':'')+'"><button type="button" data-local-back>← Regional map</button><h2 style="margin:14px 0 6px">'+esc(title)+' <small>('+esc(selectedHex)+')</small></h2><p>Six-mile parent hex · terrain-first prototype · browsing only</p>'+(map?'<div style="display:flex;gap:6px;flex-wrap:wrap;margin:12px 0">'+toggles+'</div><div class="gw-terrain-layout">'+svg+side+'</div><p style="color:#c9b894">'+(regionTerrain(selectedHex)?'Approved regional artwork · aspect-preserving crop. Marker positions and suggested routes remain provisional.':'Provisional topographic illustration.')+' Grid matches the regional point-up orientation; cells are visual references, not extra travel units. Select locations by marker or the area selector.</p>'+(map.connections||[]).filter(x=>x&&typeof x.hex==='string'&&localMaps[x.hex]).map(x=>'<div style="border-top:1px solid #62563a;padding-top:10px"><button type="button" data-local-neighbour="'+esc(x.hex)+'">'+esc(x.label)+' ↗</button><p>'+esc(x.note)+'</p></div>').join('')+((map.conditional||[]).length?'<h3>Conditional discoveries</h3><div style="display:grid;gap:8px">'+buttons(map.conditional)+'</div>':''):'<p>No detailed local layout loaded. Connect or reload the private vault.</p>')+'</div>';
}
document.addEventListener('click',e=>{if(!gm())return;const b=e.target.closest('[data-terrain-layer],[data-local-card]');if(!b)return;if(b.dataset.terrainLayer&&Object.hasOwn(terrainLayers,b.dataset.terrainLayer))terrainLayers[b.dataset.terrainLayer]=!terrainLayers[b.dataset.terrainLayer];else if(b.dataset.localCard)selectedLocalCard=b.dataset.localCard;mount();});
document.addEventListener('click',e=>{if(!gm())return;const b=e.target.closest('[data-local-back],[data-local-area],[data-local-neighbour]');if(!b)return;if(b.hasAttribute('data-local-back')){localMapOpen=false;terrainExpanded=false;resetTerrainCamera();selectedHex='all';}else if(b.dataset.localArea){localArea=b.dataset.localArea;}else if(b.dataset.localNeighbour){selectedHex=b.dataset.localNeighbour;localArea='C';selectedLocalCard='';resetTerrainCamera();}mount();});
