document.addEventListener('click',e=>{const b=e.target.closest('[data-map-action]');if(!b||!gm())return;const a=b.dataset.mapAction;if(a==='in')zoomTerrain(1.25);else if(a==='out')zoomTerrain(.8);else if(a==='fit'){resetTerrainCamera();syncTerrainCamera();}else if(a==='expand'){terrainExpanded=!terrainExpanded;mount();}});
document.addEventListener('wheel',e=>{if(!gm()||!e.target.closest('[data-terrain-svg]'))return;e.preventDefault();zoomTerrain(e.deltaY<0?1.15:1/1.15);},{passive:false});
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('[data-terrain-svg]');if(!svg||!gm()||e.button!==0||terrainCamera.zoom<=1)return;terrainDrag={svg,id:e.pointerId,x:e.clientX,y:e.clientY,cx:terrainCamera.x,cy:terrainCamera.y,moved:false};});
document.addEventListener('pointermove',e=>{const d=terrainDrag;if(!d||d.id!==e.pointerId||!gm())return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(!d.moved&&Math.hypot(dx,dy)<5)return;if(!d.moved){d.moved=true;d.svg.classList.add('gw-dragging');try{d.svg.setPointerCapture(e.pointerId);}catch{}}const r=d.svg.getBoundingClientRect(),scale=Math.min(r.width/(terrainBase.w/terrainCamera.zoom),r.height/(terrainBase.h/terrainCamera.zoom));if(!scale)return;const w=terrainBase.w/terrainCamera.zoom,h=terrainBase.h/terrainCamera.zoom;terrainCamera.x=Math.max(42+w/2,Math.min(458-w/2,d.cx-dx/scale));terrainCamera.y=Math.max(-8+h/2,Math.min(460-h/2,d.cy-dy/scale));syncTerrainCamera();});
function finishTerrainDrag(e){const d=terrainDrag;if(!d||d.id!==e.pointerId)return;terrainDrag=null;d.svg.classList.remove('gw-dragging');try{d.svg.releasePointerCapture(e.pointerId);}catch{}if(d.moved){terrainSuppressClick=true;setTimeout(()=>{terrainSuppressClick=false;},250);}}
document.addEventListener('pointerup',finishTerrainDrag);document.addEventListener('pointercancel',finishTerrainDrag);
document.addEventListener('click',e=>{if(terrainSuppressClick&&e.target.closest('[data-terrain-svg]')){e.preventDefault();e.stopImmediatePropagation();terrainSuppressClick=false;}},true);
