let vaultHandle=null, privateNotes={}, privateVersion=0, privateMessage='', privateBusy=false, privateEpoch=0;
const fullGM=()=>document.body.dataset.role==='gm'&&document.body.dataset.gmPreview!=='true';

let localArt={},localRun=new Set();
function regionTerrain(key){return fullGM()?localArt['terrain:'+key]:null;}
function terrainLayerMarkup(key){const url=regionTerrain(key);return url?'<image data-private-art href="'+esc(url)+'" x="0" y="0" width="500" height="470" preserveAspectRatio="xMidYMid slice" pointer-events="none"/>':terrainSvg(key);}
const runGM=()=>fullGM()&&location.hash==='#/gm-session';
function revokeArt(){Object.values(localArt).forEach(u=>URL.revokeObjectURL(u));localArt={};}
function artMarkup(c,large=false){const id=c.id,k=registryEntry(c)?'registry:'+id:id.startsWith('s6-region-a')?'west':id.startsWith('s6-region-b')?'east':['s6-traveller','s6-pack-animal','s6-route-exchange'].includes(id)?'traveller':id==='s6-examine-tracks'?'creature':null;const url=fullGM()?localArt[k]:null;return url?'<img data-private-art src="'+esc(url)+'" alt="Local canonical reference" style="'+(large?'width:100%;max-height:400px;object-fit:contain':'width:100%;height:100%;object-fit:cover')+'">':'';}
async function readPath(root,path){const parts=path.split('/');if(parts.some(p=>!p||p==='.'||p==='..'))throw Error('Invalid local path');let dir=root;for(const p of parts.slice(0,-1))dir=await dir.getDirectoryHandle(p);return (await dir.getFileHandle(parts.at(-1))).getFile();}
async function resolveArt(h,n,mapData={}){const terrainPaths=new Set(Object.values(mapData).map(m=>m.terrainAsset).filter(Boolean));const out={};for(const [k,s] of Object.entries(n)){for(const m of s.matchAll(/!\[\[([^\]|#]+?\.(?:png|jpe?g|webp))(?=[\]|#])/gi)){if(!m[1].startsWith('Attachments/')||terrainPaths.has(m[1]))continue;try{const f=await readPath(h,m[1]);if(f.size>35000000)continue;out[k]=URL.createObjectURL(f);break;}catch{}}}return out;}
function formatInline(v){let out='',last=0;for(const m of v.matchAll(/\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|([^\]]+))?\]\]/g)){out+=esc(v.slice(last,m.index));out+='<button type="button" data-local-record="'+esc(m[1])+'" style="color:#e8cb85;background:none;border:0;border-bottom:1px dotted #a58c58;cursor:pointer">'+esc(m[2]||m[1].split('/').at(-1))+'</button>';last=m.index+m[0].length;}return (out+esc(v.slice(last))).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
function markdownLocal(s){const lines=s.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n/,'').split(/\r?\n/);let out='',i=0;while(i<lines.length){const line=lines[i];if(!line.trim()||/^!\[\[/.test(line)){i++;continue;}const h=line.match(/^(#{1,6}) (.+)$/);if(h){const tag='h'+Math.min(5,h[1].length+2);out+='<'+tag+'>'+formatInline(h[2])+'</'+tag+'>';i++;continue;}if(/^\|.*\|$/.test(line)){const rows=[];while(i<lines.length&&/^\|.*\|$/.test(lines[i]))rows.push(lines[i++].slice(1,-1).split('|').map(t=>t.trim()));out+='<div style="overflow:auto"><table style="width:100%;border-collapse:collapse">'+rows.filter(row=>!row.every(v=>/^:?-+:?$/.test(v))).map((row,j)=>'<tr>'+row.map(v=>'<'+(j?'td':'th')+' style="text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid #62563a">'+formatInline(v)+'</'+(j?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>';continue;}if(/^[-*] /.test(line)){out+='<ul>';while(i<lines.length&&/^[-*] /.test(lines[i]))out+='<li>'+formatInline(lines[i++].slice(2))+'</li>';out+='</ul>';continue;}out+='<p>'+formatInline(line)+'</p>';i++;}return '<div style="overflow-wrap:anywhere;line-height:1.65;font-size:15px">'+out+'</div>';}
async function openRelated(name){if(!fullGM()||!vaultHandle)return;const epoch=privateEpoch;let body=Object.values(privateNotes).find(s=>noteHeading(s)===name.split('/').at(-1)||noteHeading(s).startsWith(name.split('/').at(-1)+' — '));if(!body){try{if(name.includes('/'))body=await(await readPath(vaultHandle,name.endsWith('.md')?name:name+'.md')).text();else for(const folder of ['04 Locations','03 NPCs','06 Creatures and Beasts','90 GM Only','00 Dashboard','05 Factions']){try{body=await(await readPath(vaultHandle,folder+'/'+name+'.md')).text();break;}catch{}}}catch{}}if(epoch!==privateEpoch||!fullGM())return;const d=document.createElement('dialog');d.dataset.privateRelated='1';d.style.cssText='width:min(940px,92vw);max-height:86vh;overflow:auto;background:#191a14;color:#eee5cd;border:1px solid #ad9457;padding:24px';d.innerHTML='<button type="button" data-close-related style="float:right">Close</button><small>PRIVATE LOCAL RECORD</small><h2>'+esc(name)+'</h2>'+(body?markdownLocal(body):'<p>Record not found in the selected local folders.</p>');d.querySelector('[data-close-related]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();}

let runCollapsed=new Set(),runFocus='',runScrollPending=false;
const pinStorage='greywake.private.run.refs.v1';let pinSession='',restoringVault=false,restoreAttempted=false;
function restorePins(){if(!fullGM()||!session||pinSession===session)return;pinSession=session;localRun.clear();runCollapsed.clear();runFocus='';try{const s=JSON.parse(localStorage.getItem(pinStorage)||'{}')[session]||{};for(const id of s.ids||[])if(typeof id==='string')localRun.add(id);for(const id of s.collapsed||[])if(localRun.has(id))runCollapsed.add(id);if(localRun.has(s.focus))runFocus=s.focus;}catch{}}
function savePins(){if(!fullGM()||!pinSession)return;try{const s=JSON.parse(localStorage.getItem(pinStorage)||'{}');s[pinSession]={ids:[...localRun],collapsed:[...runCollapsed],focus:runFocus};localStorage.setItem(pinStorage,JSON.stringify(s));}catch{}}
function vaultDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('greywake-private-vault-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('handles');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function vaultStore(mode,value){const db=await vaultDB();try{return await new Promise((resolve,reject)=>{const t=db.transaction('handles',mode==='get'?'readonly':'readwrite'),s=t.objectStore('handles');const q=mode==='get'?s.get('root'):mode==='clear'?s.delete('root'):s.put(value,'root');t.oncomplete=()=>resolve(q.result);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}finally{db.close();}}
async function restoreVault(){if(!fullGM()||restoreAttempted||restoringVault||vaultHandle||privateBusy||!(gm()||runGM()))return;restoreAttempted=true;restoringVault=true;const epoch=privateEpoch;try{const h=await vaultStore('get');if(!h||!fullGM()||epoch!==privateEpoch)return;vaultHandle=h;const permission=await h.queryPermission({mode:'read'});if(!fullGM()||epoch!==privateEpoch)return;if(permission==='granted')await loadPrivate(false);else {privateMessage='Reconnect vault to restore your preparation';privateVersion++;}}catch{}finally{restoringVault=false;schedule();}}
async function reconnectVault(){if(!fullGM())return;try{if(vaultHandle&&await vaultHandle.requestPermission({mode:'read'})==='granted'){await loadPrivate(false);return;}}catch{}await loadPrivate(true);}
function pinPrivate(c){if(!fullGM()||!privateCard(c))return;localRun.add(c.id);runCollapsed.delete(c.id);runFocus=c.id;runScrollPending=true;savePins();terrainExpanded=false;document.getElementById('gwPrepDetail')?.close();window.GreywakeNavigation.navigate('#/gm-session');schedule();}
const privateRunCSS='.gw-private-run-board{border:1px solid #ad9457;background:#1b1e17;border-radius:7px;padding:18px;margin:16px 0;color:#e9dfc7}.gw-private-run-board h2{margin:6px 0 8px}.gw-private-run-board p,.gw-private-run-board li,.gw-private-run-board td{font-size:15px!important;line-height:1.6!important;color:#e0d8c5!important}.gw-private-run-board small{color:#c9b894;font:600 11px system-ui,sans-serif;letter-spacing:.07em}.gw-private-run-board button{background:#302b20;color:#eadab4;border:1px solid #8b764d;border-radius:4px;padding:8px 11px;font:600 13px system-ui,sans-serif;cursor:pointer}.gw-private-run-board button:hover,.gw-private-run-board button:focus-visible{background:#4c4129;outline:2px solid #d2ae66;outline-offset:2px}.gw-private-run-board button[aria-pressed=true]{background:#b99752;color:#171711}.gw-private-run-card{border:1px solid #62563a;background:#25291f;border-radius:6px;margin:14px 0;overflow:hidden;scroll-margin-top:95px}.gw-private-run-card.gw-run-focus{border-color:#d7b46f}.gw-private-run-head{display:flex;gap:12px;justify-content:space-between;align-items:start;padding:14px;flex-wrap:wrap}.gw-private-run-head h3{font-size:23px!important;margin:5px 0}.gw-private-run-content{padding:0 14px 15px}.gw-private-run-content img{border-radius:5px}.gw-run-block{border:1px solid #62563a;border-radius:5px;padding:12px;margin:10px 0;background:#1c2018}.gw-run-block h4{font-size:16px!important;color:#e4c98d;margin:0 0 6px}.gw-run-block[data-run-tone=opening]{border-left:3px solid #b99752}.gw-run-block[data-run-tone=secret]{border-left:3px solid #9c735b}.gw-private-run-board details{border-top:1px solid #62563a;padding:9px 0}.gw-private-run-board summary{cursor:pointer;color:#e4c98d;font-weight:600;line-height:1.5}.gw-private-run-board .gw-run-body-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:10px}.gw-private-run-board .gw-run-body-grid .gw-run-block{margin:0}.gw-run-actions{display:flex;flex-wrap:wrap;gap:6px;align-items:center}.gw-private-run-board [data-local-record]{min-height:0;padding:0;color:#e8cb85;background:none;border:0;border-bottom:1px dotted #a58c58;border-radius:0;font:inherit}';
function ensurePrivateRunStyle(){if(document.getElementById('gwPrivateRunStyle'))return;const s=document.createElement('style');s.id='gwPrivateRunStyle';s.textContent=privateRunCSS;document.head.append(s);}
function runSections(body){
 const lines=body.split(/\r?\n/),out=[];let current={title:'Location and situation',text:[],tone:'opening'};
 const flush=()=>{if(current.text.join('\n').trim())out.push(current);};
 for(const line of lines){const m=line.match(/^\s*(?:\*\*([^*]+):\*\*|([A-Za-z][A-Za-z /-]{1,30}):)\s*(.*)$/);if(m){flush();const title=(m[1]||m[2]).trim();current={title,text:[m[3]],tone:/^opening$/i.test(title)?'opening':/^GM /i.test(title)?'secret':'normal'};}else current.text.push(line);}
 flush();return out;
}
function privateRunCardHtml(c){
 const p=privateCard(c),collapsed=runCollapsed.has(c.id);
 const controls='<div class="gw-run-actions"><button type="button" data-private-run-focus="'+esc(c.id)+'" aria-pressed="'+(runFocus===c.id)+'">Focus</button><button type="button" data-private-run-collapse="'+esc(c.id)+'" aria-expanded="'+(!collapsed)+'">'+(collapsed?'Expand':'Collapse')+'</button><button type="button" data-private-run-remove="'+esc(c.id)+'">Remove</button></div>';
 let body='';
 if(!collapsed){
  if(!p)body='<p>Private source unavailable. Reconnect or reload the vault.</p>';
  else{const blocks=runSections(p.body);const primary=blocks.filter(b=>!/^(source|assets)/i.test(b.title));const sources=blocks.filter(b=>/^(source|assets)/i.test(b.title));body='<div class="gw-private-run-content">'+artMarkup(c,true)+'<div class="gw-run-body-grid">'+primary.map(b=>'<section class="gw-run-block" data-run-tone="'+b.tone+'"><h4>'+esc(b.title)+'</h4>'+markdownLocal(b.text.join('\n'))+'</section>').join('')+'</div><details><summary>Daggerheart adjudication and running guidance</summary>'+guidanceHtml(c.id)+'</details>'+sources.map(b=>'<details><summary>'+esc(b.title)+'</summary>'+markdownLocal(b.text.join('\n'))+'</details>').join('')+p.notes.map(n=>'<details><summary>'+esc(n.title)+'</summary>'+privateText(n.body)+'</details>').join('')+'<div class="gw-run-actions" style="margin-top:10px"><button type="button" data-private-run-view="'+esc(c.id)+'">Full preparation window</button><button type="button" data-private-run-map="'+esc(cardHex(c)==='unassigned'?'all':cardHex(c))+'">Browse source hex</button></div></div>';}
 }
 return '<article class="gw-private-run-card'+(runFocus===c.id?' gw-run-focus':'')+'" data-private-run-id="'+esc(c.id)+'"><header class="gw-private-run-head"><div><small>'+esc(c.readiness)+' · '+esc(c.kind)+' · PRIVATE</small><h3>'+esc(shownTitle(c))+'</h3></div>'+controls+'</header>'+body+'</article>';
}
function mountPrivateRun(){
 if(!runGM()){document.querySelector('[data-private-run-nav]')?.remove();return;}const host=document.getElementById('gmDynamicScene');if(!host)return;ensurePrivateRunStyle();
 let panel=document.querySelector('[data-private-run]');if(!panel){panel=document.createElement('section');panel.dataset.privateRun='1';host.after(panel);}
 const sig=JSON.stringify([privateVersion,[...localRun],[...runCollapsed],runFocus,cards?.map(c=>c.id),privateBusy,privateMessage]);
 if(panel.dataset.sig===sig&&document.querySelector('[data-private-run-nav]')){if(runScrollPending){runScrollPending=false;requestAnimationFrame(()=>{if(runGM())[...panel.querySelectorAll('[data-private-run-id]')].find(el=>el.dataset.privateRunId===runFocus)?.scrollIntoView({block:'start',behavior:'smooth'});});}return;}panel.dataset.sig=sig;
 const selected=[...localRun].map(id=>cards?.find(c=>c.id===id)||{id,title:'Saved reference · '+id,readiness:'Waiting for source',kind:'reference'});
 let nav=document.querySelector('[data-private-run-nav]');if(!nav){nav=document.createElement('nav');nav.dataset.privateRunNav='1';nav.setAttribute('aria-label','Pinned private references');host.before(nav);}const navHtml=selected.length?'<div class="gw-private-run-board" style="padding:10px"><small>PRIVATE REFERENCES · QUICK ACCESS</small><div class="gw-run-actions">'+selected.map(c=>'<button type="button" data-private-run-focus="'+esc(c.id)+'">'+esc(shownTitle(c))+'</button>').join('')+'</div></div>':'';if(nav.dataset.sig!==navHtml){nav.innerHTML=navHtml;nav.dataset.sig=navHtml;}
 panel.innerHTML='<div class="gw-private-run-board"><small>GM ONLY · LOCAL REFERENCE</small><h2>Private RUN preparation</h2><p>Read and run the pinned preparation here. These references do not change the shared scene, party position or canon.</p>'+(!Object.keys(privateNotes).length?'<p role="status">'+esc(privateMessage||'Reconnect vault to restore your preparation')+'</p><button type="button" data-vault-action="reconnect" '+(privateBusy?'disabled':'')+'>Reconnect vault to restore your preparation</button>':'')+(!selected.length?'<p>No private cards pinned. Open PREP and choose Pin private card to RUN.</p>':selected.map(privateRunCardHtml).join(''))+'</div>';
 if(runScrollPending){runScrollPending=false;requestAnimationFrame(()=>{if(!runGM())return;[...panel.querySelectorAll('[data-private-run-id]')].find(el=>el.dataset.privateRunId===runFocus)?.scrollIntoView({block:'start',behavior:'smooth'});});}
}
document.addEventListener('click',e=>{if(!runGM())return;const b=e.target.closest('[data-private-run-collapse],[data-private-run-focus],[data-private-run-map]');if(!b)return;if(b.dataset.privateRunCollapse){const id=b.dataset.privateRunCollapse;if(runCollapsed.has(id))runCollapsed.delete(id);else runCollapsed.add(id);savePins();mountPrivateRun();}else if(b.dataset.privateRunFocus){runFocus=b.dataset.privateRunFocus;runCollapsed.delete(runFocus);runScrollPending=true;savePins();mountPrivateRun();}else if(b.dataset.privateRunMap){selectedHex=b.dataset.privateRunMap;localArea='C';localMapOpen=selectedHex!=='all';selectedLocalCard='';resetTerrainCamera();window.GreywakeNavigation.navigate('#/gm-prep');schedule();}});
document.addEventListener('click',e=>{if(!fullGM())return;const b=e.target.closest('[data-local-record],[data-private-pin],[data-private-run-view],[data-private-run-remove]');if(!b)return;if(b.dataset.localRecord)openRelated(b.dataset.localRecord);else if(b.dataset.privatePin)pinPrivate(cards?.find(c=>c.id===b.dataset.privatePin));else if(b.dataset.privateRunView)viewPrep(cards?.find(c=>c.id===b.dataset.privateRunView));else if(b.dataset.privateRunRemove){localRun.delete(b.dataset.privateRunRemove);runCollapsed.delete(b.dataset.privateRunRemove);if(runFocus===b.dataset.privateRunRemove)runFocus='';savePins();mountPrivateRun();}});

const noteHeading=s=>(s.match(/^# (.+)$/m)||[])[1]||'';
function sections(s,level){const rx=new RegExp('^'+'#'.repeat(level)+' (.+)$','gm');return [...s.matchAll(rx)].map(m=>{const start=m.index+m[0].length;const next=s.slice(start).search(new RegExp('^#{1,'+level+'} ','m'));return {title:m[1].trim(),body:s.slice(start,next<0?s.length:start+next).trim()};});}
function sectionNamed(s,level,name){return sections(s||'',level).find(x=>x.title===name);}
function privateCard(c){
 if(!c||!fullGM())return null;
 const meta=registryEntry(c);if(meta){const body=localSourceFiles[meta.path];if(!body)return null;const sec=meta.heading?sectionNamed(body,meta.level||2,meta.heading):{title:noteHeading(body)||c.title,body};const notes=(meta.related||[]).map(path=>localSourceFiles[path]).filter(Boolean).map(body=>({title:noteHeading(body),body}));return sec?{title:sec.title,body:sec.body,notes}:null;}
 if(!String(c.id).startsWith('s6-'))return null;
 const k=c.id;let sec,notes=[];
 if(k.startsWith('s6-region-')){
  const a=k.startsWith('s6-region-a'),src=a?privateNotes.west:privateNotes.east;
  const group=sectionNamed(src,2,a?'Three discoverable sites':'Nodes');
  sec=sections(group?.body||'',3)[Number(k.slice(-1))-1];
  if(src)notes.push({title:noteHeading(src),body:src});
  if(privateNotes.region)notes.push({title:noteHeading(privateNotes.region),body:privateNotes.region});
 }else{
  sec=sectionNamed(privateNotes.session,2,c.title);
  if(['s6-traveller','s6-pack-animal','s6-route-exchange'].includes(k)&&privateNotes.traveller)notes.push({title:noteHeading(privateNotes.traveller),body:privateNotes.traveller});
  if(k==='s6-examine-tracks'&&privateNotes.creature)notes.push({title:noteHeading(privateNotes.creature),body:privateNotes.creature});
 }
 return sec?{title:sec.title.split(' — ')[0],body:sec.body,notes}:null;
}
const shownTitle=c=>privateCard(c)?.title||c.title;
function localHexLabel(k){if(fullGM()&&k==='0,-4'&&privateNotes.west)return noteHeading(privateNotes.west);if(fullGM()&&k==='1,-2'&&privateNotes.traveller)return noteHeading(privateNotes.traveller).split(' — ')[0];return hexLabels[k]||'Uncharted';}
