function clearPrivate(forget=false){if(forget){localRun.clear();runCollapsed.clear();runFocus='';savePins();vaultStore('clear').catch(()=>{});}pinSession='';restoreAttempted=false;privateEpoch++;terrainExpanded=false;resetTerrainCamera();document.querySelectorAll('[data-prep-hex-browser]').forEach(el=>el.remove());localMaps={};localMapOpen=false;localArea='C';revokeArt();localRun.clear();runCollapsed.clear();runFocus='';runScrollPending=false;document.querySelectorAll('[data-private-related],[data-private-run],[data-private-run-nav],[data-private-art]').forEach(el=>el.remove());vaultHandle=null;privateNotes={};localRegistry={};localSourceFiles={};loadedSourceSession='';privateVersion++;privateMessage='Private notes cleared.';privateBusy=false;document.getElementById('gwPrepDetail')?.close();document.querySelectorAll('[data-private-vault]').forEach(el=>el.remove());mount();}
async function findLocalNotes(dir,accept){
 const result={};for await(const [name,h] of dir.entries()){if(h.kind!=='file'||!name.endsWith('.md'))continue;const f=await h.getFile();if(f.size>2000000)continue;const s=await f.text();const key=accept(name,s);if(key&&!result[key])result[key]=s;}return result;
}
async function loadPrivate(pick){
 if(!(gm()||runGM())||privateBusy)return;
 if(typeof window.showDirectoryPicker!=='function'){privateMessage='Folder access is unavailable in this browser. Use desktop Chrome or Edge.';privateVersion++;mount();return;}
 const epoch=++privateEpoch;privateBusy=true;privateMessage='Reading selected local vault…';privateVersion++;mount();
 try{
  const h=pick?await window.showDirectoryPicker({mode:'read'}):vaultHandle;
  if(!h)throw Error('Select the Greywake vault folder first.');
  const locations=await h.getDirectoryHandle('04 Locations'),npcs=await h.getDirectoryHandle('03 NPCs'),gmDir=await h.getDirectoryHandle('90 GM Only');
  const n={...await findLocalNotes(locations,(name,s)=>/^hex:\s*["']?\(0,-4\)/m.test(s)?'west':/^hex:\s*["']?\(\+1,-4\)/m.test(s)?'east':null),
   ...await findLocalNotes(npcs,(name,s)=>s.includes('(+1,-2)')&&s.includes('Session Six')&&s.includes('travelling north')?'traveller':null),
   ...await findLocalNotes(gmDir,(name,s)=>name==='Session 06 — Card Preparation.md'?'session':/^type: regional-preparation/m.test(s)&&s.includes('(0,-4)')&&s.includes('(+1,-4)')?'region':null)};
  try{const creatures=await h.getDirectoryHandle('06 Creatures and Beasts');const tracks=sectionNamed(n.session,2,'Examine the animal tracks');Object.assign(n,await findLocalNotes(creatures,(name,s)=>tracks?.body.includes('[['+name.slice(0,-3)+']]')?'creature':null));}catch{}
  if(epoch!==privateEpoch||!fullGM())return;
  const registry=Object.create(null),sourceFiles=Object.create(null);try{const raw=JSON.parse(await(await readPath(h,'90 GM Only/Preparation Index.json')).text());if(raw.schema!==1||!raw.cards||typeof raw.cards!=='object')throw Error('Invalid preparation index');for(const [id,m] of Object.entries(raw.cards)){if(!m||!sourcePath(m.path)||typeof m.heading!=='string'||![1,2,3,4,5,6].includes(m.level||2))continue;registry[id]={path:m.path,heading:m.heading,level:m.level||2,hex:typeof m.hex==='string'&&/^-?\d+,-?\d+$/.test(m.hex)?m.hex:null,related:Array.isArray(m.related)?m.related.filter(sourcePath):[]};for(const path of [m.path,...registry[id].related])try{if(!Object.hasOwn(sourceFiles,path)){const f=await readPath(h,path);if(f.size<=2000000)sourceFiles[path]=await f.text();}}catch{}if(Object.hasOwn(sourceFiles,m.path))n['registry:'+id]=sourceFiles[m.path];}}catch(e){if(e.name!=='NotFoundError')privateMessage='Preparation index unavailable: '+String(e.message||e);}
  if(!Object.keys(n).length&&!Object.keys(registry).length)throw Error('No preparation sources found. Check the selected vault and preparation index.');
  let mapData={};try{const f=await(await gmDir.getFileHandle('Local Hex Maps — Prototype.md')).getFile();mapData=parseLocalMaps(await f.text());}catch{}const art=await resolveArt(h,n,mapData);for(const [key,map] of Object.entries(mapData)){if(typeof map.terrainAsset!=='string'||!map.terrainAsset.startsWith('Attachments/')||!/\.(png|jpe?g|webp)$/i.test(map.terrainAsset))continue;try{const f=await readPath(h,map.terrainAsset);if(f.size<=35000000)art['terrain:'+key]=URL.createObjectURL(f);}catch{}}if(epoch!==privateEpoch||!fullGM()){Object.values(art).forEach(u=>URL.revokeObjectURL(u));return;}revokeArt();localArt=art;localMaps=mapData;vaultHandle=h;privateNotes=n;localRegistry=registry;localSourceFiles=sourceFiles;loadedSourceSession=session;vaultStore('put',h).catch(()=>{});privateMessage='Private vault loaded locally · '+Object.keys(n).length+' source notes · no upload.';
 }catch(e){if(epoch===privateEpoch)privateMessage=e.name==='AbortError'?'Folder selection cancelled.':String(e.message||e);}
 finally{if(epoch===privateEpoch){privateBusy=false;privateVersion++;mount();mountPrivateRun();}}
}
