 const ranked=cards.some(c=>relevance(c)>0);const scoped=prepScope==='relevant'&&selectedHex==='all'&&!prepQuery.trim()&&ranked;const visible=cards.filter(c=>(!scoped||relevance(c)>0)&&(selectedHex==='all'||cardHex(c)===selectedHex)&&(prepKind==='all'||c.kind===prepKind)&&[shownTitle(c),c.title,c.detail,c.kind,c.readiness].join(' ').toLowerCase().includes(prepQuery.toLowerCase().trim())).sort((a,b)=>relevance(b)-relevance(a));
 const count=parent.querySelector('[data-prep-count]');const countText=visible.length+' of '+cards.length+' cards'+(prepScope==='relevant'&&!ranked?' · no mapped matches; showing available cards':'');if(count&&count.textContent!==countText)count.textContent=countText;
 const sig=JSON.stringify([selectedHex,cards,privateVersion,prepQuery,prepKind,prepScope,currentHex(),[...localRun]]);if(grid.dataset.prepSignature===sig)return;grid.dataset.prepSignature=sig;
